private bool GetAssistantResult()
        {
            if (ProductConfiguration.GetInstance().TransportUnitConfig.IsOppositeSex)
            {
                return ProductConfiguration.GetInstance().OppositeSexConfiguration.OppositeSexConfigs.AssistantSuccess();
            }
            else
            {
                List<AssistantState> list = this.GetAssistantStates();
                foreach (var item in list)
                {
                    if (item.State == AssistantStateEnum.UnAble)
                    {
                        return false;
                    }
                }

                return true;
            }
        }

public List<AssistantState> GetAssistantStates()
        {
            List<AssistantState> list = new List<AssistantState>();
            list.Add(this.TUPosition);
            list.Add(this.TUAdjust);
            list.Add(this.TUIdentification);
            list.Add(this.TUHeightMeasurement);
            list.Add(this.SubstratePosition);
            list.Add(this.SubstrateAdjust);
            list.Add(this.SubstrateInkDot);
            list.Add(this.SubstrateIdentification);
            list.Add(this.SubstrateHeightMeasurement);
            list.Add(this.ModulePosition);
            list.Add(this.ModuleAdjust);
            list.Add(this.ModuleInkDot);
            list.Add(this.ModuleHeightMeasurement);
            list.Add(this.BadModuleTable);
            list.Add(this.Mapping); 
            list.Add(this.ModuleIdentification);

            return list;
        }

public bool AssistantSuccess()
        {
            if (this.MatterTypeEnum == EntityTypeEnum.BondPosition)
            {
                return this.Config.IsAfterBondAssistant && this.Config.IsEpoxyCheckAssistant
                                                        && this.Config.IsMeasureHeightAssistant
                                                        && this.Config.IsPrAssistant
                                                        && this.AssistantPos;
            }
            else
            {
                if (this.DownConfigs.Count == 0)
                {
                    return false;
                }

                return !this.DownConfigs.Exists(it => !it.AssistantSuccess());
            }
        }

public bool GetIsEpoxyCheckAssistant()
        {
            if (!this.EpoxyCheck)
            {
                return true;
            }
            else
            {
                PostBondInspection postBondInspection =
                    (PostBondInspection)PostBondInspectionRepository.GetInstance().Find(this.EpoxyCheckName);
                if (postBondInspection == null)
                {
                    return false;
                }

                return postBondInspection.IsAssistantSucceed;
            }
        }

public bool GetIsIsAfterBondAssistant()
        {
            if (!this.AfterBond)
            {
                return true;
            }
            else
            {
                PostBondInspection postBondInspection =
                    (PostBondInspection)PostBondInspectionRepository.GetInstance().Find(this.AfterBondName);
                if (postBondInspection == null)
                {
                    return false;
                }

                return postBondInspection.IsAssistantSucceed;
            }
        }

public enum AssistantStateEnum
    {
        /// <summary>
        /// 通过
        /// </summary>
        Able = 0,

        /// <summary>
        /// 未通过
        /// </summary>
        UnAble = 1,

        /// <summary>
        /// 禁止
        /// </summary>
        ForBidden = 2,
    }
